const output = $input.first().json.output || '';

const start = output.indexOf('##PEDIDO_CREADO##');
const end = output.indexOf('##FIN_PEDIDO##');

if (start === -1 || end === -1) {
  return [{ json: { wasCreated: false } }];
}

const jsonStr = output.substring(start + '##PEDIDO_CREADO##'.length, end).trim();

try {
  const product = JSON.parse(jsonStr);
  return [{ json: { ...product, wasCreated: true } }];
} catch (e) {
  return [{ json: { wasCreated: false, _error: e.message, _raw: jsonStr } }];
}
